using Microsoft.Extensions.Options; namespace Backend.Api.Auth; public sealed class SessionMiddleware(RequestDelegate next,ILogger<SessionMiddleware> logger,IOptions<SessionOptions> options){public async Task InvokeAsync(HttpContext context,SessionService sessions){if(HttpMethods.IsPost(context.Request.Method)&&context.Request.Path.Equals("/auth/login",StringComparison.OrdinalIgnoreCase)){await next(context);return;}var cookie=context.Request.Cookies[options.Value.CookieName];if(!sessions.Validate(cookie,DateTimeOffset.UtcNow,out var user)){logger.LogWarning("Unauthenticated request rejected: {Method} {Path}",context.Request.Method,context.Request.Path);context.Response.StatusCode=StatusCodes.Status401Unauthorized;return;}context.Items["authenticated_user"]=user!;await next(context);}}